## Replay full-memory outcomes generated by the pristine upstream public API.
## No production Ragnarok decoder, memory representation or execution engine is imported.

import std/[assertions, syncio, envvars]
import ../standard_memory

proc word(data: string, offset, length: int): uint64 =
  ## Decode a bounded little-endian field of the independent reference format.
  assert offset >= 0 and offset <= data.len and length <= data.len-offset
  result = 0
  for index in 0..<length:
    result = result or (uint64(byte(data[offset+index])) shl (8*index))

proc apply(memory: var StandardMemory, storing: bool, width: byte, address: uint32): Access =
  ## Select the same fixed-width scalar operation as the Rust witness.
  if storing:
    case width
    of 1: result = store[1](memory, address, 0x8877665544332211'u64)
    of 2: result = store[2](memory, address, 0x8877665544332211'u64)
    of 4: result = store[4](memory, address, 0x8877665544332211'u64)
    of 8: result = store[8](memory, address, 0x8877665544332211'u64)
    else: assert false, "foreign reference width"
  else:
    case width
    of 1: result = load[1](memory, address)
    of 2: result = load[2](memory, address)
    of 4: result = load[4](memory, address)
    of 8: result = load[8](memory, address)
    else: assert false, "foreign reference width"

var data = ""
try:
  # A missing oracle must stop verification; the candidate never generates expectations.
  data = readFile("build/pvm-faithful/standard-memory.bin")
except:
  quit 2
assert data.len >= 60 and data[0..7] == "PVFSMM01"
var geometry = default(array[12, uint32])
for index in 0..<12: geometry[index] = uint32(word(data, 8+4*index, 4))
let layout = MemoryLayout(pageSize: geometry[0], roAddress: geometry[1], rwAddress: geometry[2],
  stackLow: geometry[3], stackHigh: geometry[4], auxAddress: geometry[5], roSize: geometry[6],
  rwSize: geometry[7], stackSize: geometry[8], auxSize: geometry[9], heapBase: geometry[10],
  maxHeapSize: geometry[11], ro: sharedBytes([1'u8, 2, 3, 4]), rw: sharedBytes([5'u8, 6, 7, 8]))
let bases = [geometry[1], geometry[2], geometry[3], geometry[5]]
let sizes = [geometry[6], geometry[7], geometry[8], geometry[9]]
var snapshotSize = 0
for size in sizes:
  assert size <= 1048576
  snapshotSize += int(size)
let count = int(word(data, 56, 4))
assert count > 0 and count <= 1024
assert data.len == 60+count*(16+snapshotSize)
let corrupt = getEnv("RAGNAROK_FAITHFUL_CORRUPT") == "1"
var cursor = 60
for row in 0..<count:
  # Construct fresh mutable state, then reproduce either initial, populated or reset memory.
  let phase = byte(data[cursor])
  let storing = byte(data[cursor+1]) == 1
  let width = byte(data[cursor+2])
  let address = uint32(word(data, cursor+3, 4))
  let expectedExit = byte(data[cursor+7])
  let expectedA0 = word(data, cursor+8, 8)
  assert phase <= 2 and byte(data[cursor+1]) <= 1 and expectedExit <= 1
  cursor += 16
  var memory = newStandardMemory(layout)
  if phase != 0:
    for region in 1..3:
      var seed = newSeq[byte](int(sizes[region]))
      for index in 0..<seed.len: seed[index] = 0xa5
      assert memory.write(bases[region], seed) == AccessKind.Ok
    if phase == 2: memory.reset(layout)
  let answer = apply(memory, storing, width, address)
  assert ord(answer.kind) == int(expectedExit)
  let a0 = if storing or answer.kind != AccessKind.Ok: 0x8877665544332211'u64 else: answer.value
  assert a0 == expectedA0
  for region in 0..3:
    # Compare every mapped byte, including unchanged regions and non-resident zero padding.
    var actual = newSeq[byte](int(sizes[region]))
    assert memory.read(bases[region], actual)
    for index in 0..<actual.len:
      let expected = byte(data[cursor+index]) xor (if corrupt and row == 0 and region == 0 and
          index == 0: 1'u8 else: 0'u8)
      assert actual[index] == expected, "faithful full memory mismatch"
    cursor += actual.len
assert cursor == data.len
echo "faithful standard full-memory reference passed: ", count
